import{_ as a,o as e,c as r,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const h=JSON.parse('{"title":"Transactions Extractor","description":"","frontmatter":{"title":"Transactions Extractor"},"headers":[],"relativePath":"docs/tools/transactions-extractor.md","filePath":"docs/tools/transactions-extractor.md","lastUpdated":1791955898000}'),o={name:"docs/tools/transactions-extractor.md"};function n(i,t,c,d,l,p){return e(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="transactions-extractor" tabindex="-1">Transactions Extractor <a class="header-anchor" href="#transactions-extractor" aria-label="Permalink to &quot;Transactions Extractor&quot;">​</a></h1><p>The Transactions Extractor turns a bank or credit-card statement PDF, or a CSV or spreadsheet export, into structured transactions. It runs automatically whenever you <a href="/docs/getting-started/add-first-source">add a source</a> that looks like a statement, so most of the time you won&#39;t use it directly.</p><p>Use the tool itself to check a file before adding it: drop in a statement and see exactly what would be imported. The result is shown in the tool and can be saved as a local CSV file.</p><h2 id="parsers" tabindex="-1">Parsers <a class="header-anchor" href="#parsers" aria-label="Permalink to &quot;Parsers&quot;">​</a></h2><p>Support for each statement format comes from an individual parser. OrbySystems ships with parsers for the common major institutions; see <a href="/docs/personal-finance/supported-institutions">Supported institutions</a>.</p><p>Parsers run in a sandbox with no network access, and can read only the one statement they&#39;re given.</p><p>If yours isn&#39;t supported, or reads a statement wrongly, use <a href="/docs/tools/add-new-institution">Add New Institution</a>.</p>',7)])])}const m=a(o,[["render",n]]);export{h as __pageData,m as default};
